TEXT title "选择剂量配比" x=300 y=20 z=1 block=true
TEXT option1 "低剂量" x=100 y=200 z=2 block=true
TEXT option2 "中剂量" x=300 y=200 z=2 block=true
TEXT option3 "高剂量" x=500 y=200 z=2 block=true
IMAGE ham1 "" x=100 y=300 w=100 h=100 z=3 vis=false
IMAGE ham2 "" x=300 y=300 w=100 h=100 z=3 vis=false
IMAGE ham3 "" x=500 y=300 w=100 h=100 z=3 vis=false
CLICK option1 enabled=true action=commands
    VAR selected = "低"
    VAR dose = 1
    STYLE option1 {"display":"none"}
    STYLE option2 {"display":"none"}
    STYLE option3 {"display":"none"}
    TEXT result "已选择：低剂量" x=300 y=400 z=4 block=true
    IMAGE ham1 resource=哈密瓜 x=300 y=200 w=200 h=200 z=5 vis=true animation={"entry":{"animId":"向下滑入"}}
CLICK option2 enabled=true action=commands
    VAR selected = "中"
    VAR dose = 2
    STYLE option1 {"display":"none"}
    STYLE option2 {"display":"none"}
    STYLE option3 {"display":"none"}
    TEXT result "已选择：中剂量" x=300 y=400 z=4 block=true
    IMAGE ham1 resource=哈密瓜 x=300 y=200 w=200 h=200 z=5 vis=true animation={"entry":{"animId":"向左滑入"}}
CLICK option3 enabled=true action=commands
    VAR selected = "高"
    VAR dose = 3
    STYLE option1 {"display":"none"}
    STYLE option2 {"display":"none"}
    STYLE option3 {"display":"none"}
    TEXT result "已选择：高剂量" x=300 y=400 z=4 block=true
    IMAGE ham1 resource=哈密瓜 x=300 y=200 w=200 h=200 z=5 vis=true animation={"entry":{"animId":"向右滑入"}}

IMAGE card_bg images/old/通用按钮背景.png x=300 y=200 w=200 h=280 z=1
IMAGE card_front images/默认选项.png x=300 y=200 w=200 h=280 z=2 animation={"entry":{"animId":"从零放大"},"loop":{"animId":"上下悬浮"}}
CLICK card_front action=flip front=card_front back=card_bg showBack=true

IMAGE 桌子背景 images/桌子背景 x=0 y=0 w=800 h=600 z=0
IMAGE intro images/intro x=300 y=200 w=200 h=200 z=1 animation={"entry":{"animId":"从零放大"},"loop":{"animId":"上下悬浮"}}
CLICK intro action=flip front=images/intro back=images/桌子背景 showBack=true

VAR score = 0
IMAGE card count-2 x=300 y=200 w=200 h=300 z=1 animation={"entry":{"animId":"向上滑入"},"loop":{"animId":"向上滑入"}}
CLICK card action=flip front=count-2 back=count-1 showBack=false

VAR selectedCard = ""
IMAGE card1 images/问题03.png x=100 y=200 w=200 h=280 z=1 animation={"entry":{"animId":"向左滑入"},"loop":{"animId":"旋转"}}
IMAGE card2 images/问题03.png x=350 y=200 w=200 h=280 z=1 animation={"entry":{"animId":"向右滑入"},"loop":{"animId":"旋转"}}
IMAGE card3 images/问题03.png x=600 y=200 w=200 h=280 z=1 animation={"entry":{"animId":"向左滑入"},"loop":{"animId":"旋转"}}
SELECT card1 enabled=true var=selectedCard single=true overlay=card1_sel effect=pulse
    VAR selectedCard = "card1"
SELECT card2 enabled=true var=selectedCard single=true overlay=card2_sel effect=pulse
    VAR selectedCard = "card2"
SELECT card3 enabled=true var=selectedCard single=true overlay=card3_sel effect=pulse
    VAR selectedCard = "card3"

VAR seen_220 = false
IMAGE card images/失败弹窗2.png x=300 y=200 w=200 h=200 z=1 animation={"entry":{"animId":"向上滑入"}}
CLICK card action=commands
    VAR seen_220 = true
    TEXT result "工具匹配完成" x=250 y=300 z=2 block=true dismiss=true animation={"entry":{"animId":"向下滑入"}}

